create or replace function public.planint_normalize_urgency() returns trigger language plpgsql security invoker set search_path='' as $$ begin new.urgency:=case lower(btrim(coalesce(new.urgency,''))) when '' then 'Media' when 'normal' then 'Media' when 'urgente' then 'Alta' when 'baja' then 'Baja' when 'media' then 'Media' when 'alta' then 'Alta' when 'crítica' then 'Crítica' when 'critica' then 'Crítica' else new.urgency end; return new; end $$; revoke all on function public.planint_normalize_urgency() from public,anon,authenticated; create trigger planint_activities_normalize_urgency before insert or update on public.planint_activities for each row execute function public.planint_normalize_urgency(); update public.planint_activities set urgency=urgency; alter table public.planint_activities alter column urgency set default 'Media'; alter table public.planint_activities add constraint planint_activities_urgency_values check (urgency in ('Baja','Media','Alta','Crítica'));
